import React from "react";

function Features() {
  return (
    <div className="page">
      <h1>Our Features</h1>
      <ul>
        <li>✅ No Hidden Fees</li>
        <li>✅ Smart Budgeting</li>
        <li>✅ Secure Transactions</li>
      </ul>
    </div>
  );
}

export default Features;
